+using Microsoft.ML;
+using TicketClassifier.Models;
+
+namespace TicketClassifier.Services;
+
+public class TicketClassifierService
+{
+    private readonly MLContext _mlContext;
+    private ITransformer _model = null!;
+    private PredictionEngine<TicketInput, TicketPrediction> _predictionEngine = null!;
+    private string[] _categoryLabels = [];
+
+    public EvaluationMetrics Metrics { get; private set; } = new();
+
+    public TicketClassifierService()
+    {
+        _mlContext = new MLContext(seed: 42);
+    }
+
+    public void Train(string dataPath)
+    {
+        var dataView = _mlContext.Data.LoadFromTextFile<TicketInput>(
+            dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);
+
+        var pipeline = _mlContext.Transforms.Conversion.MapValueToKey("Label", nameof(TicketInput.Category))
+            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketInput.Subject)))
+            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketInput.Description)))
+            .Append(_mlContext.Transforms.Concatenate("Features", "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketInput.Priority)))
+            .Append(_mlContext.Transforms.NormalizeMinMax("Features"))
+            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
+            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));
+
+        _model = pipeline.Fit(dataView);
+        _predictionEngine = _mlContext.Model.CreatePredictionEngine<TicketInput, TicketPrediction>(_model);
+
+        // Extract category labels from the trained model's key-value mapping
+        var transformedData = _model.Transform(dataView);
+        var labelColumn = transformedData.Schema["PredictedLabel"];
+        VBuffer<ReadOnlyMemory<char>> keyValues = default;
+        // Get labels from the Label key column instead
+        var labelKeyColumn = transformedData.Schema["Label"];
+        labelKeyColumn.GetKeyValues(ref keyValues);
+        _categoryLabels = keyValues.DenseValues().Select(v => v.ToString()).ToArray();
+
+        Evaluate(dataView);
+    }
+
+    private void Evaluate(IDataView dataView)
+    {
+        var predictions = _model.Transform(dataView);
+        var metrics = _mlContext.MulticlassClassification.Evaluate(predictions, labelColumnName: "Label");
+
+        Metrics = new EvaluationMetrics
+        {
+            MacroAccuracy = (float)metrics.MacroAccuracy,
+            MicroAccuracy = (float)metrics.MicroAccuracy,
+            LogLoss = (float)metrics.LogLoss,
+            LogLossReduction = (float)metrics.LogLossReduction
+        };
+    }
+
+    public PredictionResponse Predict(TicketRequest request)
+    {
+        var input = new TicketInput
+        {
+            Subject = request.Subject,
+            Description = request.Description,
+            Priority = request.Priority
+        };
+
+        var prediction = _predictionEngine.Predict(input);
+
+        var confidence = new Dictionary<string, float>();
+        for (int i = 0; i < _categoryLabels.Length && i < prediction.Score.Length; i++)
+        {
+            confidence[_categoryLabels[i]] = prediction.Score[i];
+        }
+
+        return new PredictionResponse
+        {
+            PredictedCategory = prediction.PredictedCategory,
+            Confidence = confidence
+        };
+    }
+}
+

